        end else if (expB == 5'b00000) begin
            // B is zero
            result = A;
        end else if (abs_sum == 12'b0) begin
            // Result is zero
            result = 16'b0;
        end else if (exp_result > 31) begin
            // Overflow to infinity
            result = {signS, 5'b11111, 10'b0};
        end else if (exp_result <= 0) begin
            // Underflow to zero
            result = 16'b0;
        end else begin
