        out[31]    = sign_Ans; 
    end

    task PENC32;
        input   [31:0] D;
        output  [4:0]  Q;
        output         vld;
        reg [3:0] Q2_h, Q2_l;
        reg       vld2_h, vld2_l;
        begin
            PENC16( D[31:16],   Q2_h,   vld2_h);
            PENC16( D[15:0],    Q2_l,   vld2_l);
            Q[4]    = vld2_h;
            Q[3:0]  = vld2_h ? Q2_h : Q2_l;
            vld     = vld2_h | vld2_l;
        end
    endtask

    task PENC16;
        input   [15:0] D;
        output  [3:0]  Q;
        output         vld;
        reg [2:0] Q1_h, Q1_l;
        reg       vld1_h, vld1_l;
        begin
            PENC8( D[15:8],  Q1_h,   vld1_h);
            PENC8( D[7:0],   Q1_l,   vld1_l);
            Q[3]    = vld1_h;
            Q[2:0]  = vld1_h ? Q1_h : Q1_l;
            vld     = vld1_h | vld1_l;
        end
    endtask

    task PENC8;
        input   [7:0] D;
        output  [2:0] Q;
        output        vld;
        begin
            vld  = D[7] | D[6] | D[5] | D[4] | D[3] | D[2] | D[1] | D[0];
            Q[2] = D[7] | D[6] | D[5] | D[4];
            Q[1] = (D[7] | D[6] | D[5] | D[4]) ? (D[7] | D[6]) : (D[3] | D[2]);
            Q[0] = (D[7] | D[6] | D[5] | D[4]) ? (D[7] | (~D[6] & D[5])) : (D[3] | (~D[2] & D[1]));
        end
    endtask
endmodule


module top_module(
    input       [31:0]  src1,
    input       [31:0]  src2,
    output reg  [31:0]  out
    );

    reg [66:0]  fraction_1;
    reg [66:0]  fraction_2;
    reg [66:0]  fraction_Ans;
    reg [7:0]   exponent_1;
    reg [7:0]   exponent_2;
    reg [7:0]   exponent_Ans;
    reg         sign_1;
    reg         sign_2;
    reg         sign_Ans;
    reg  [4:0]  norm_count;
    reg         norm_vld;

    // Combinational implementation of FP32 addition
    always @* begin
        fraction_1  = {2'd0, src1[22:0], 42'd0};  
        fraction_2  = {2'd0, src2[22:0], 42'd0};  
        exponent_1  = src1[30:23];
        exponent_2  = src2[30:23];
        sign_1      = src1[31];
        sign_2      = src2[31]; 

        if(exponent_1 == 0) begin
            exponent_1 = 1;
            fraction_1[65] = 0;  
        end else begin
            fraction_1[65] = 1;
        end

        if(exponent_2 == 0) begin
            exponent_2 = 1;
            fraction_2[65] = 0;  
        end else begin
            fraction_2[65] = 1;
        end

        if(exponent_1 > exponent_2) begin
            fraction_2 = fraction_2 >> (exponent_1 - exponent_2);
            exponent_Ans = exponent_1;
        end else if(exponent_1 < exponent_2) begin
            fraction_1 = fraction_1 >> (exponent_2 - exponent_1);
            exponent_Ans = exponent_2;
        end else begin
            exponent_Ans = exponent_1;  
        end

        if(sign_1 == sign_2) begin
            fraction_Ans = fraction_1 - fraction_2;
            sign_Ans = sign_1;
        end else begin
            if(fraction_1 >= fraction_2) begin
                fraction_Ans = fraction_1 - fraction_2;
                sign_Ans = sign_1;
            end else begin
                fraction_Ans = fraction_2 - fraction_1;
                sign_Ans = sign_2;
            end
        end

        if(fraction_Ans[66]) begin
            fraction_Ans = fraction_Ans >> 1;
            exponent_Ans = exponent_Ans + 1;
        end

        if(fraction_Ans[65] == 0) begin
            PENC32({11'b0, fraction_Ans[64:42]}, norm_count, norm_vld);  
            fraction_Ans = fraction_Ans << (5'd23 - norm_count);  
            exponent_Ans = exponent_Ans + norm_count - 5'd23;  
        end

        out[22:0]  = fraction_Ans[64:42];
        out[30:23] = exponent_Ans[7:0];
        out[31]    = sign_Ans; 
    end

    task PENC32;
        input   [31:0] D;
        output  [4:0]  Q;
        output         vld;
        reg [3:0] Q2_h, Q2_l;
        reg       vld2_h, vld2_l;
        begin
            PENC16( D[31:16],   Q2_h,   vld2_h);
            PENC16( D[15:0],    Q2_l,   vld2_l);
            Q[4]    = vld2_h;
            Q[3:0]  = vld2_h ? Q2_h : Q2_l;
            vld     = vld2_h | vld2_l;
        end
    endtask

    task PENC16;
        input   [15:0] D;
        output  [3:0]  Q;
        output         vld;
        reg [2:0] Q1_h, Q1_l;
        reg       vld1_h, vld1_l;
        begin
            PENC8( D[15:8],  Q1_h,   vld1_h);
            PENC8( D[7:0],   Q1_l,   vld1_l);
            Q[3]    = vld1_h;
            Q[2:0]  = vld1_h ? Q1_h : Q1_l;
            vld     = vld1_h | vld1_l;
        end
    endtask

    task PENC8;
        input   [7:0] D;
        output  [2:0] Q;
        output        vld;
        begin
            vld  = D[7] | D[6] | D[5] | D[4] | D[3] | D[2] | D[1] | D[0];
            Q[2] = D[7] | D[6] | D[5] | D[4];
            Q[1] = (D[7] | D[6] | D[5] | D[4]) ? (D[7] | D[6]) : (D[3] | D[2]);
            Q[0] = (D[7] | D[6] | D[5] | D[4]) ? (D[7] | (~D[6] & D[5])) : (D[3] | (~D[2] & D[1]));
        end
    endtask
endmodule

module_code:
module top_module (
    input  logic       clk,
    input  logic       reset,
    input  logic       start,
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [15:0] product,
    output logic       done
);
    logic        busy;
    logic [3:0]  count;
    logic [15:0] acc;
    logic [15:0] multiplicand;
    logic [7:0]  multiplier;

    always_ff @(posedge clk) begin
        if (reset) begin
            busy <= 1'b0;
            count <= 4'd0;
            acc <= 16'd0;
            multiplicand <= 16'd0;
            multiplier <= 8'd0;
            product <= 16'd0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;

            if (!busy) begin
                if (start) begin
                    busy <= 1'b1;
                    count <= 4'd0;
                    acc <= 16'd0;
                    multiplicand <= {8'd0, a};
                    multiplier <= b;
                end
            end else begin
                logic [15:0] acc_next;
                acc_next = acc + (multiplier[0] ? multiplicand : 16'd0);

                acc <= acc_next;
                multiplicand <= (multiplicand << 1);
                multiplier <= (multiplier >> 1);
                count <= count + 4'd1;

                if (count == 4'd7) begin
                    busy <= 1'b0;
                    product <= acc_next;
                    done <= 1'b1;
                end
            end
        end
    end
endmodule

testbench:
`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input clk,
    output logic reset,
    output logic start,
    output logic [7:0] a,
    output logic [7:0] b,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    task automatic run_op(input logic [7:0] a_in, input logic [7:0] b_in);
        int i;
        @(negedge clk);
        a <= a_in;
        b <= b_in;
        start <= 1'b1;

        // Deassert start (start is a 1-cycle pulse).
        @(negedge clk);
        start <= 1'b0;

        // During the 8-cycle operation, change inputs and inject a spurious start pulse.
        for (i = 0; i < 8; i = i + 1) begin
            @(negedge clk);
            a <= $random;
            b <= $random;
            start <= (i == 3);  // should be ignored while busy
        end

        @(negedge clk);
        start <= 1'b0;
    endtask

    initial begin
        reset <= 1'b1;
        start <= 1'b0;
        a <= 8'd0;
        b <= 8'd0;

        @(negedge clk) wavedrom_start("8-bit serial multiplier");

        repeat(2) @(posedge clk);
        reset <= 1'b0;

        // Directed tests.
        run_op(8'd3,   8'd5);
        run_op(8'd0,   8'd123);
        run_op(8'd1,   8'd255);
        run_op(8'd255, 8'd255);

        // Random tests.
        repeat(20) run_op($random, $random);

        wavedrom_stop();
        repeat(20) @(posedge clk, negedge clk) begin
            a <= $random;
            b <= $random;
            start <= 1'b0;
        end
        $finish;
    end

endmodule

module tb();

    typedef struct packed {
        int errors;
        int errortime;
        int errors_product;
        int errortime_product;
        int errors_done;
        int errortime_done;

        int clocks;
    } stats;

    stats stats1;


    wire[511:0] wavedrom_title;
    wire wavedrom_enable;
    int wavedrom_hide_after_time;

    reg clk=0;
    initial forever
        #5 clk = ~clk;

    logic reset;
    logic start;
    logic [7:0] a;
    logic [7:0] b;
    logic [15:0] product_ref;
    logic [15:0] product_dut;
    logic done_ref;
    logic done_dut;

    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(1, stim1.clk, tb_mismatch ,clk,reset,start,a,b,product_ref,product_dut,done_ref,done_dut );
    end


    wire tb_match;       // Verification
    wire tb_mismatch = ~tb_match;

    stimulus_gen stim1 (
        .clk,
        .* ,
        .reset,
        .start,
        .a,
        .b );
    RefModule good1 (
        .clk,
        .reset,
        .start,
        .a,
        .b,
        .product(product_ref),
        .done(done_ref) );

    TopModule top_module1 (
        .clk,
        .reset,
        .start,
        .a,
        .b,
        .product(product_dut),
        .done(done_dut) );


    bit strobe = 0;
    task wait_for_end_of_timestep;
        repeat(5) begin
            strobe <= !strobe;  // Try to delay until the very end of the time step.
            @(strobe);
        end
    endtask


    final begin
        if (stats1.errors_product) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "product", stats1.errors_product, stats1.errortime_product);
        else $display("Hint: Output '%s' has no mismatches.", "product");

        if (stats1.errors_done) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "done", stats1.errors_done, stats1.errortime_done);
        else $display("Hint: Output '%s' has no mismatches.", "done");

        $display("Hint: Total mismatched samples is %1d out of %1d samples\n", stats1.errors, stats1.clocks);
        $display("Simulation finished at %0d ps", $time);
        $display("Mismatches: %1d in %1d samples", stats1.errors, stats1.clocks);
    end

    // Verification: XORs on the right makes any X in good_vector match anything, but X in dut_vector will only match X.
    assign tb_match = ( { product_ref, done_ref } === ( { product_ref, done_ref } ^ { product_dut, done_dut } ^ { product_ref, done_ref } ) );
    // Use explicit sensitivity list here. @(*) causes NetProc::nex_input() to be called when trying to compute
    // the sensitivity list of the @(strobe) process, which isn't implemented.
    always @(posedge clk, negedge clk) begin

        stats1.clocks++;
        if (!tb_match) begin
            if (stats1.errors == 0) stats1.errortime = $time;
            stats1.errors++;
        end
        if (product_ref !== ( product_ref ^ product_dut ^ product_ref ))
        begin if (stats1.errors_product == 0) stats1.errortime_product = $time;
            stats1.errors_product = stats1.errors_product+1'b1; end

        if (done_ref !== ( done_ref ^ done_dut ^ done_ref ))
        begin if (stats1.errors_done == 0) stats1.errortime_done = $time;
            stats1.errors_done = stats1.errors_done+1'b1; end

    end

   // add timeout after 100K cycles
   initial begin
     #1000000
     $display("TIMEOUT");
     $finish();
   end

endmodule

