`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input clk,
    output logic [3:0] a,
    output logic [3:0] b,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    initial begin
        {a,b} <= 8'd0;
        @(negedge clk) wavedrom_start("4x4 parallel array multiplier");

        // Directed tests.
        @(posedge clk) begin a <= 4'd0;  b <= 4'd0;  end
        @(posedge clk) begin a <= 4'd15; b <= 4'd0;  end
        @(posedge clk) begin a <= 4'd0;  b <= 4'd15; end
        @(posedge clk) begin a <= 4'd15; b <= 4'd15; end
        @(posedge clk) begin a <= 4'd9;  b <= 4'd6;  end

        repeat(25) @(posedge clk) {a,b} <= $random;
        wavedrom_stop();
        repeat(75) @(posedge clk, negedge clk) {a,b} <= $random;
        $finish;
    end

endmodule

module tb();

    typedef struct packed {
        int errors;
        int errortime;
        int errors_product;
        int errortime_product;

        int clocks;
    } stats;

    stats stats1;


    wire[511:0] wavedrom_title;
    wire wavedrom_enable;
    int wavedrom_hide_after_time;

    reg clk=0;
    initial forever
        #5 clk = ~clk;

    logic [3:0] a;
    logic [3:0] b;
    logic [7:0] product_ref;
    logic [7:0] product_dut;

    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(1, stim1.clk, tb_mismatch ,a,b,product_ref,product_dut );
    end


    wire tb_match;       // Verification
    wire tb_mismatch = ~tb_match;

    stimulus_gen stim1 (
        .clk,
        .* ,
        .a,
        .b );
    RefModule good1 (
        .a,
        .b,
        .product(product_ref) );

    TopModule top_module1 (
        .a,
        .b,
        .product(product_dut) );


    bit strobe = 0;
    task wait_for_end_of_timestep;
        repeat(5) begin
            strobe <= !strobe;  // Try to delay until the very end of the time step.
            @(strobe);
        end
    endtask


    final begin
        if (stats1.errors_product) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "product", stats1.errors_product, stats1.errortime_product);
        else $display("Hint: Output '%s' has no mismatches.", "product");

        $display("Hint: Total mismatched samples is %1d out of %1d samples\n", stats1.errors, stats1.clocks);
        $display("Simulation finished at %0d ps", $time);
        $display("Mismatches: %1d in %1d samples", stats1.errors, stats1.clocks);
    end

    // Verification: XORs on the right makes any X in good_vector match anything, but X in dut_vector will only match X.
    assign tb_match = ( { product_ref } === ( { product_ref } ^ { product_dut } ^ { product_ref } ) );
    // Use explicit sensitivity list here. @(*) causes NetProc::nex_input() to be called when trying to compute
    // the sensitivity list of the @(strobe) process, which isn't implemented.
    always @(posedge clk, negedge clk) begin

        stats1.clocks++;
        if (!tb_match) begin
            if (stats1.errors == 0) stats1.errortime = $time;
            stats1.errors++;
        end
        if (product_ref !== ( product_ref ^ product_dut ^ product_ref ))
        begin if (stats1.errors_product == 0) stats1.errortime_product = $time;
            stats1.errors_product = stats1.errors_product+1'b1; end

    end

   // add timeout after 100K cycles
   initial begin
     #1000000
     $display("TIMEOUT");
     $finish();
   end

endmodule

