module top_module (
    input  logic       clk,
    input  logic       reset,
    input  logic       start,
    input  logic [7:0] dividend,
    input  logic [7:0] divisor,
    output logic [7:0] quotient,
    output logic [7:0] remainder,
    output logic       done
);
    logic       busy;
    logic [3:0] count;

    logic [7:0] dividend_shift;
    logic [7:0] divisor_latched;
    logic [7:0] quotient_shift;
    logic [8:0] rem;

    always_ff @(posedge clk) begin
        if (reset) begin
            busy <= 1'b0;
            count <= 4'd0;
