        int errortime;
        int errors_out_re;
        int errortime_out_re;
        int errors_out_im;
        int errortime_out_im;
        int errors_out_valid;
        int errortime_out_valid;

        int clocks;
    } stats;

    stats stats1;


    wire[511:0] wavedrom_title;
    wire wavedrom_enable;
    int wavedrom_hide_after_time;

    reg clk=0;
    initial forever
        #5 clk = ~clk;

    logic reset;
    logic in_valid;
    logic [15:0] a_re;
    logic [15:0] a_im;
    logic [15:0] b_re;
    logic [15:0] b_im;

