        .clk,
        .reset,
        .in_valid,
        .a_re,
        .a_im,
        .b_re,
        .b_im,
        .out_re(out_re_dut),
        .out_im(out_im_dut),
        .out_valid(out_valid_dut) );


    bit strobe = 0;
    task wait_for_end_of_timestep;
        repeat(5) begin
