`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input clk,
    output logic        reset,
    output logic        start,
    output logic [15:0] radicand,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    task automatic run_op(input logic [15:0] n_in);
        int i;
        @(negedge clk);
        radicand <= n_in;
        start <= 1'b1;

        @(negedge clk);
        start <= 1'b0;

        // During the 8-cycle operation, change inputs and inject a spurious start pulse.
        for (i = 0; i < 8; i = i + 1) begin
            @(negedge clk);
            radicand <= $random;
            start <= (i == 4);  // should be ignored while busy
        end

        @(negedge clk);
        start <= 1'b0;
    endtask

    initial begin
        reset <= 1'b1;
        start <= 1'b0;
        radicand <= 16'd0;

        @(negedge clk) wavedrom_start("Integer sqrt (8-cycle iterative)");

        repeat(2) @(posedge clk);
        reset <= 1'b0;

        // Directed tests.
        run_op(16'd0);
        run_op(16'd1);
        run_op(16'd2);
        run_op(16'd3);
        run_op(16'd4);
        run_op(16'd15);
        run_op(16'd16);
        run_op(16'd255);
        run_op(16'd256);
        run_op(16'd65535);

        // Random tests.
        repeat(20) run_op($random);

        wavedrom_stop();
