module_code:
module top_module (
    input  logic       clk,
    input  logic       reset,
    input  logic       start,
    input  logic [7:0] tx_data,
    input  logic       miso,
    output logic       mosi,
    output logic       sclk,
    output logic       cs_n,
    output logic [7:0] rx_data,
    output logic       busy,
    output logic       done
);
    logic       phase;  // 0=low, 1=high
    logic [2:0] bit_idx;
    logic [7:0] tx_shift;
    logic [7:0] rx_shift;
    logic       done_pending;

    always_ff @(posedge clk) begin
        if (reset) begin
            mosi <= 1'b0;
            sclk <= 1'b0;
            cs_n <= 1'b1;
            rx_data <= 8'd0;
            busy <= 1'b0;
            done <= 1'b0;

            phase <= 1'b0;
            bit_idx <= 3'd0;
            tx_shift <= 8'd0;
            rx_shift <= 8'd0;
            done_pending <= 1'b0;
        end else begin
            done <= 1'b0;

            if (!busy) begin
                // Idle defaults
                sclk <= 1'b0;
                cs_n <= 1'b1;
                mosi <= 1'b0;
                done_pending <= 1'b0;

                if (start) begin
                    busy <= 1'b1;
                    cs_n <= 1'b0;
                    sclk <= 1'b0;
                    tx_shift <= tx_data;
                    rx_shift <= 8'd0;
                    bit_idx <= 3'd7;
                    mosi <= tx_data[7];
                    phase <= 1'b1;  // next cycle is HIGH half-cycle (sample)
                end
            end else begin
                if (phase == 1'b0) begin
                    // LOW half-cycle
                    sclk <= 1'b0;
                    if (done_pending) begin
                        busy <= 1'b0;
                        cs_n <= 1'b1;
                        mosi <= 1'b0;
                        done <= 1'b1;
                        rx_data <= rx_shift;
                        done_pending <= 1'b0;
                        phase <= 1'b0;
                    end else begin
                        mosi <= tx_shift[bit_idx];
                        phase <= 1'b1;
                    end
                end else begin
                    // HIGH half-cycle: sample MISO
                    sclk <= 1'b1;
                    rx_shift[bit_idx] <= miso;
                    phase <= 1'b0;
                    if (bit_idx == 3'd0) begin
                        done_pending <= 1'b1;
                    end else begin
                        bit_idx <= bit_idx - 3'd1;
                    end
                end
            end
        end
    end
endmodule

testbench:
`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input clk,
    output logic       reset,
    output logic       start,
    output logic [7:0] tx_data,
    output logic       miso,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    // Simple deterministic "slave" response generator based on cycle count
    // after start is accepted. This avoids depending on DUT outputs.
    logic active;
    int unsigned offset;
    logic [7:0] slave_data;

    always_ff @(posedge clk) begin
        if (reset) begin
            active <= 1'b0;
            offset <= 0;
            slave_data <= 8'h00;
            miso <= 1'b1;
        end else begin
            if (!active && start) begin
                active <= 1'b1;
                offset <= 0;
                slave_data <= $random;
            end else if (active) begin
                offset <= offset + 1;
                if (offset >= 16) begin
                    active <= 1'b0;
                end
            end

            // Update MISO during LOW half-cycles so it is stable for the next HIGH sample.
            if (active && (offset[0] == 1'b0) && (offset <= 14)) begin
                int bitpos;
                bitpos = 7 - (offset >> 1);
                miso <= slave_data[bitpos];
            end else if (!active) begin
                miso <= $random;
            end
        end
    end

    task automatic run_op(input logic [7:0] tx);
        @(negedge clk);
        tx_data <= tx;
        start <= 1'b1;
        @(negedge clk);
        start <= 1'b0;
    endtask

    initial begin
        reset <= 1'b1;
        start <= 1'b0;
        tx_data <= 8'd0;
        miso <= 1'b1;

        @(negedge clk) wavedrom_start("SPI master mode0 single-byte transfer");
        repeat(2) @(posedge clk);
        reset <= 1'b0;

        // Directed + random transactions. Inject spurious starts during busy.
        run_op(8'hA5);
        repeat(3) @(negedge clk) start <= 1'b1;
        @(negedge clk) start <= 1'b0;

        run_op(8'h00);
        run_op(8'hFF);
        repeat(20) run_op($random);

        wavedrom_stop();
        repeat(40) @(posedge clk, negedge clk) begin
            tx_data <= $random;
            start <= 1'b0;
        end
        $finish;
    end

endmodule

