    logic        pslverr_ref, pslverr_dut;

    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(1, stim1.clk, tb_mismatch ,clk,reset,psel,penable,pwrite,paddr,pwdata,prdata_ref,prdata_dut,pready_ref,pready_dut,pslverr_ref,pslverr_dut );
    end

    wire tb_match;
    wire tb_mismatch = ~tb_match;

    stimulus_gen stim1 (
        .clk,
        .*,
        .reset,
        .psel,
        .penable,
        .pwrite,
        .paddr,
        .pwdata
    );

