                        rd_shift[63 - bit_pos] <= mdio_in;
                    end

                    phase <= 1'b0;
                    if (bit_pos == (TOTAL_BITS-1)) begin
                        done_pending <= 1'b1;
                    end else begin
                        bit_pos <= bit_pos + 7'd1;
                    end
                end
            end
