`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input clk,
    output logic       reset,
    output logic       start,
    output logic [7:0] data,
    output logic       dev_data_drive_low,
    output reg[511:0]  wavedrom_title,
    output reg         wavedrom_enable
);
    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    localparam int unsigned TOTAL_CYCLES = 29; // inhibit(4) + bits(22) + ack(2) + done(1)
    logic active;
    int unsigned t;
    logic ack_ok;

    always_ff @(posedge clk) begin
        if (reset) begin
            active <= 1'b0;
            t <= 0;
        end else begin
            if (!active && start) begin
                active <= 1'b1;
                t <= 0;
            end else if (active) begin
                t <= t + 1;
                if (t >= (TOTAL_CYCLES-1)) begin
                    active <= 1'b0;
                end
            end
        end
    end

    always_comb begin
        dev_data_drive_low = 1'b0;
        if (active) begin
            // ACK pulse occurs at cycles 26-27 relative to start accept.
            if ((t == 26) || (t == 27)) begin
                dev_data_drive_low = ack_ok;
            end
        end
    end

    task automatic run_op(input logic [7:0] d_in, input logic ack_in);
        @(negedge clk);
        data <= d_in;
        ack_ok <= ack_in;
        start <= 1'b1;

        // spurious starts while busy should be ignored
        repeat(4) @(negedge clk) start <= $random;
        @(negedge clk) start <= 1'b0;

        repeat(TOTAL_CYCLES+5) @(posedge clk);
    endtask

    initial begin
        reset <= 1'b1;
        start <= 1'b0;
