`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input  src_clk,
    input  dst_clk,
    input  src_ready_ref,
    output logic src_reset,
    output logic dst_reset,
    output logic src_valid,
    output logic [7:0] src_data,
    output logic dst_ready,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    // Source driver: follow ready/valid protocol and hold data stable while waiting.
    always_ff @(posedge src_clk) begin
        if (src_reset) begin
            src_valid <= 1'b0;
            src_data <= 8'd0;
        end else begin
            if (src_valid && !src_ready_ref) begin
                // Hold.
                src_valid <= 1'b1;
                src_data <= src_data;
            end else begin
                src_valid <= !($random & 3); // ~25% chance
                if (!($random & 3)) begin
                    src_data <= $random;
                end else begin
                    src_data <= src_data;
                end
            end
        end
    end

    // Destination driver: random backpressure.
    always_ff @(posedge dst_clk) begin
        if (dst_reset) begin
            dst_ready <= 1'b0;
        end else begin
            dst_ready <= $random;
        end
    end

    initial begin
        src_reset <= 1'b1;
        dst_reset <= 1'b1;
        src_valid <= 1'b0;
        src_data <= 8'd0;
        dst_ready <= 1'b0;

        wavedrom_start("CDC Req/Ack handshake (byte transfer)");

        repeat(4) @(posedge src_clk);
        repeat(2) @(posedge dst_clk);
        @(negedge src_clk) src_reset <= 1'b0;
        @(negedge dst_clk) dst_reset <= 1'b0;

        // Run for a while.
        repeat(600) @(posedge src_clk);

        wavedrom_stop();
        #1 $finish;
    end

endmodule

