`timescale 1 ps/1 ps
`define OK 12
`define INCORRECT 13


module stimulus_gen (
    input clk,
    output logic reset,
    output logic push,
    output logic pop,
    output logic [7:0] din,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    initial begin
        reset <= 1'b1;
        push <= 1'b0;
        pop <= 1'b0;
        din <= 8'd0;

        @(negedge clk) wavedrom_start("Stack memory (LIFO, depth=16, width=8)");
        repeat(2) @(posedge clk);
        reset <= 1'b0;

        // Push to full.
        repeat(16) @(posedge clk) begin
            push <= 1'b1;
            pop <= 1'b0;
            din <= $random;
        end

        // Attempt pushes while full.
        repeat(4) @(posedge clk) begin
            push <= 1'b1;
            pop <= 1'b0;
            din <= $random;
        end

        // Pop a few.
        repeat(6) @(posedge clk) begin
            push <= 1'b0;
            pop <= 1'b1;
            din <= $random;
        end

        // Replace-top operations.
        repeat(10) @(posedge clk) begin
            push <= 1'b1;
            pop <= 1'b1;
            din <= $random;
        end

        // Drain to empty.
        repeat(20) @(posedge clk) begin
            push <= 1'b0;
            pop <= 1'b1;
            din <= $random;
        end

        // Random traffic.
        repeat(200) @(posedge clk) begin
            push <= $random;
            pop <= $random;
            din <= $random;
        end

        wavedrom_stop();
        repeat(40) @(posedge clk, negedge clk) begin
            push <= 1'b0;
            pop <= 1'b0;
            din <= $random;
        end
        $finish;
    end

endmodule

module tb();

    typedef struct packed {
        int errors;
        int errortime;
        int errors_dout;
        int errortime_dout;
        int errors_full;
        int errortime_full;
        int errors_empty;
        int errortime_empty;

        int clocks;
    } stats;

    stats stats1;


    wire[511:0] wavedrom_title;
    wire wavedrom_enable;
    int wavedrom_hide_after_time;

    reg clk=0;
    initial forever
        #5 clk = ~clk;

    logic reset;
    logic push;
    logic pop;
    logic [7:0] din;

    logic [7:0] dout_ref;
    logic [7:0] dout_dut;
    logic full_ref;
    logic full_dut;
    logic empty_ref;
    logic empty_dut;

    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(1, stim1.clk, tb_mismatch ,clk,reset,push,pop,din,dout_ref,dout_dut,full_ref,full_dut,empty_ref,empty_dut );
    end


    wire tb_match;       // Verification
    wire tb_mismatch = ~tb_match;

    stimulus_gen stim1 (
        .clk,
        .* ,
        .reset,
        .push,
        .pop,
        .din );
    RefModule good1 (
        .clk,
        .reset,
        .push,
        .pop,
        .din,
        .dout(dout_ref),
        .full(full_ref),
        .empty(empty_ref) );

    TopModule top_module1 (
        .clk,
        .reset,
        .push,
        .pop,
        .din,
        .dout(dout_dut),
        .full(full_dut),
        .empty(empty_dut) );


    bit strobe = 0;
    task wait_for_end_of_timestep;
        repeat(5) begin
            strobe <= !strobe;  // Try to delay until the very end of the time step.
            @(strobe);
        end
    endtask


    final begin
        if (stats1.errors_dout) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "dout", stats1.errors_dout, stats1.errortime_dout);
        else $display("Hint: Output '%s' has no mismatches.", "dout");

        if (stats1.errors_full) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "full", stats1.errors_full, stats1.errortime_full);
        else $display("Hint: Output '%s' has no mismatches.", "full");

        if (stats1.errors_empty) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "empty", stats1.errors_empty, stats1.errortime_empty);
        else $display("Hint: Output '%s' has no mismatches.", "empty");

        $display("Hint: Total mismatched samples is %1d out of %1d samples\n", stats1.errors, stats1.clocks);
        $display("Simulation finished at %0d ps", $time);
        $display("Mismatches: %1d in %1d samples", stats1.errors, stats1.clocks);
    end

    // Verification: XORs on the right makes any X in good_vector match anything, but X in dut_vector will only match X.
    assign tb_match = ( { dout_ref, full_ref, empty_ref } === ( { dout_ref, full_ref, empty_ref } ^ { dout_dut, full_dut, empty_dut } ^ { dout_ref, full_ref, empty_ref } ) );
    // Use explicit sensitivity list here. @(*) causes NetProc::nex_input() to be called when trying to compute
    // the sensitivity list of the @(strobe) process, which isn't implemented.
    always @(posedge clk, negedge clk) begin

