                    if (count == 2'd2) begin
                        d0 <= d1;
                    end
                    count <= count - 2'd1;
                end
                2'b11: begin // in and out
                    if (count == 2'd1) begin
                        d0 <= in_data;
                    end else if (count == 2'd2) begin
                        d0 <= d1;
