//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    function automatic logic signed [15:0] rand_angle;
        int r;
        begin
            r = $random;
            if (r < 0) r = -r;
            r = r % 23041;  // 0..23040
            if ($random & 1) r = -r;
            rand_angle = r[15:0];
        end
    endfunction

    task automatic run_op(input logic signed [15:0] angle_in);
        int i;
        @(negedge clk);
        angle <= angle_in;
        start <= 1'b1;
        @(negedge clk);
        start <= 1'b0;

        // While busy (12 iterations), perturb angle and inject a spurious start pulse.
        for (i = 0; i < 12; i = i + 1) begin
            @(negedge clk);
            angle <= rand_angle();
            start <= (i == 4);
        end

        @(negedge clk);
        start <= 1'b0;

        // Gap before next operation.
        repeat(6) @(negedge clk);
    endtask

    initial begin
        reset <= 1'b1;
        start <= 1'b0;
        angle <= 16'sd0;

        @(negedge clk) wavedrom_start("CORDIC rotation (12 iters)");

        repeat(2) @(posedge clk);
        @(negedge clk) reset <= 1'b0;

        // Directed angles (degrees*256).
        run_op(16'sd0);        // 0 deg
        run_op(16'sd7680);     // 30 deg
        run_op(16'sd11520);    // 45 deg
        run_op(-16'sd11520);   // -45 deg
        run_op(16'sd23040);    // 90 deg
        run_op(-16'sd23040);   // -90 deg

        // Random angles.
        repeat(20) run_op(rand_angle());

        wavedrom_stop();
        repeat(40) @(posedge clk, negedge clk) begin
            angle <= rand_angle();
            start <= 1'b0;
        end
        $finish;
    end

endmodule

