                    y_next = y + y_shift;
                    z_next = z - atan_i;
                end else begin
                    x_next = x + x_shift;
                    y_next = y - y_shift;
                    z_next = z + atan_i;
                end

                x <= x_next;
                y <= y_next;
                z <= z_next;
                iter <= iter - 4'd1;

                if (iter == (NITER-1)) begin
                    busy <= 1'b0;
                    cos_out <= x_next[15:0];
                    sin_out <= y_next[15:0];
                    done <= 1'b1;
                end
            end
        end
    end
