                if (z >= 0) begin
                    x_next = x - x_shift;
                    y_next = y + y_shift;
                    z_next = z - atan_i;
                end else begin
                    x_next = x + x_shift;
                    y_next = y - y_shift;
                    z_next = z + atan_i;
                end

                x <= x_next;
                y <= y_next;
                z <= z_next;
