    stats stats1;


    wire[511:0] wavedrom_title;
    wire wavedrom_enable;
    int wavedrom_hide_after_time;

    reg clk=0;
    initial forever
        #5 clk = ~clk;

    logic arst;
    logic srst_ref;
    logic srst_dut;

    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(1, stim1.clk, tb_mismatch ,clk,arst,srst_ref,srst_dut );
    end


    wire tb_match;       // Verification
    wire tb_mismatch = ~tb_match;

    stimulus_gen stim1 (
        .clk,
        .* ,
        .arst );
    RefModule good1 (
        .clk,
        .arst,
        .srst(srst_ref) );

    TopModule top_module1 (
        .clk,
        .arst,
        .srst(srst_dut) );


    bit strobe = 0;
    task wait_for_end_of_timestep;
        repeat(5) begin
            strobe <= !strobe;  // Try to delay until the very end of the time step.
            @(strobe);
        end
    endtask


    final begin
        if (stats1.errors_srst) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "srst", stats1.errors_srst, stats1.errortime_srst);
