module stimulus_gen (
    input clk,
    output logic reset,
    output logic [1:0] coin,
    output reg[511:0] wavedrom_title,
    output reg wavedrom_enable
);


// Add two ports to module stimulus_gen:
//    output [511:0] wavedrom_title
//    output reg wavedrom_enable

    task wavedrom_start(input[511:0] title = "");
    endtask

    task wavedrom_stop;
        #1;
    endtask

    initial begin
        reset <= 1'b1;
        coin <= 2'b00;
        @(negedge clk) wavedrom_start("Vending machine (price=30)");

        repeat(3) @(posedge clk);
        @(negedge clk) reset <= 1'b0;

        // Directed sequences.
        @(negedge clk) coin <= 2'b11; // 25
        @(negedge clk) coin <= 2'b01; // 5 -> dispense, change 0
        @(negedge clk) coin <= 2'b11; // 25
        @(negedge clk) coin <= 2'b10; // 10 -> dispense, change 5
        @(negedge clk) coin <= 2'b00;

        // Random coins.
        repeat(300) @(negedge clk) coin <= $random;

        wavedrom_stop();
        repeat(80) @(posedge clk, negedge clk) coin <= $random;
        $finish;
    end

endmodule

module tb();

    typedef struct packed {
        int errors;
        int errortime;
        int errors_dispense;
        int errortime_dispense;
        int errors_change;
        int errortime_change;

        int clocks;
    } stats;

    stats stats1;


    wire[511:0] wavedrom_title;
    wire wavedrom_enable;
    int wavedrom_hide_after_time;

    reg clk=0;
    initial forever
        #5 clk = ~clk;

    logic reset;
    logic [1:0] coin;
    logic dispense_ref;
    logic [5:0] change_ref;
    logic dispense_dut;
    logic [5:0] change_dut;

    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(1, stim1.clk, tb_mismatch ,clk,reset,coin,dispense_ref,change_ref,dispense_dut,change_dut );
    end


    wire tb_match;       // Verification
    wire tb_mismatch = ~tb_match;

    stimulus_gen stim1 (
        .clk,
        .* ,
        .reset,
        .coin );
    RefModule good1 (
        .clk,
        .reset,
        .coin,
        .dispense(dispense_ref),
        .change(change_ref) );

    TopModule top_module1 (
        .clk,
        .reset,
        .coin,
        .dispense(dispense_dut),
        .change(change_dut) );


    bit strobe = 0;
    task wait_for_end_of_timestep;
        repeat(5) begin
            strobe <= !strobe;  // Try to delay until the very end of the time step.
            @(strobe);
        end
    endtask


    final begin
        if (stats1.errors_dispense) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "dispense", stats1.errors_dispense, stats1.errortime_dispense);
        else $display("Hint: Output '%s' has no mismatches.", "dispense");

        if (stats1.errors_change) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "change", stats1.errors_change, stats1.errortime_change);
        else $display("Hint: Output '%s' has no mismatches.", "change");

        $display("Hint: Total mismatched samples is %1d out of %1d samples\n", stats1.errors, stats1.clocks);
        $display("Simulation finished at %0d ps", $time);
        $display("Mismatches: %1d in %1d samples", stats1.errors, stats1.clocks);
    end

    // Verification: XORs on the right makes any X in good_vector match anything, but X in dut_vector will only match X.
    assign tb_match = ( { dispense_ref, change_ref } === ( { dispense_ref, change_ref } ^ { dispense_dut, change_dut } ^ { dispense_ref, change_ref } ) );
